export default function Home(){
 const[view,setView]=useState<View>("dashboard"),[query,setQuery]=useState(""),[people,setPeople]=useState(initialPeople),[selected,setSelected]=useState(initialPeople[0]),[panel,setPanel]=useState(false);
 const list=useMemo(()=>people.filter(p=>`${p.name} ${p.id} ${p.program}`.includes(query)),[query]);
 const open=(p:typeof initialPeople[number])=>{setSelected(p);setPanel(true)};
 const updateWorkflow=(state:string,tone:string,due:string)=>{Object.assign(selected,{state,tone,due});setSelected({...selected});setPeople([...people])};
 const openWhatsApp=()=>{const digits=selected.phone.replace(/\D/g,"").replace(/^0/,"966");const message=`مرحباً ${selected.name}، معك فريق سلوكيرا بخصوص تسجيلك في برنامج ${selected.program}. يسعدنا خدمتك واستكمال الإجراء معك.`;window.open(`https://wa.me/${digits}?text=${encodeURIComponent(message)}`,"_blank","noopener,noreferrer")};
 const selectedDetails=selected as typeof selected&{email?:string;orderId?:string};
 return <main className="shell" dir="rtl">
  <aside className="sidebar"><div className="brand"><i>س</i><div><b>سلوكيرا</b><span>مركز العمليات</span></div></div><div className="workspace"><i/><div><b>بيئة العمل</b><span>متصل وآمن</span></div><em>⌄</em></div><nav>{navGroups.map(group=><section className="nav-group" key={group.label}><p className="nav-label">{group.label}</p>{group.items.map(([id,label,icon,badge])=>{const Icon=navIcons[icon];return <button key={id} className={view===id?"active":""} onClick={()=>setView(id)}><i><Icon size={17} strokeWidth={1.9}/></i>{label}{badge&&<em>{badge}</em>}</button>})}</section>)}</nav><div className="health"><span>سلامة النظام</span><b>كل الأنظمة تعمل</b><strong>99.9%</strong><i><u/></i></div><div className="profile"><i>أع</i><div><b>أحمد العلي</b><span>مدير النظام</span></div><button>⋯</button></div></aside>
  <section className="main"><header className="topbar"><div className="top-logo"><i>س</i><b>سلوكيرا</b></div><label><i>⌕</i><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="ابحث عن عميل، رقم طلب أو برنامج..."/></label><button className="bell">♢<i/></button><button className="primary" onClick={()=>setView("new")}>＋ تسجيل جديد</button></header><div className="content"><header className="heading"><div><h1>{titles[view][0]}</h1><p>{titles[view][1]}</p></div><span>اليوم · 21 يوليو 2026</span></header>
   {view==="dashboard"&&<><WelcomeToday onOpenTasks={()=>setView("work")}/><LiveDashboard/></>}
   {view==="work"&&<LiveWork/>}
   {view==="customers"&&<LiveCustomers query={query} open={open}/>}
   {view==="reservations"&&<Reservations/>}
   {view==="contact"&&<LiveAcademy focus="contact"/>}
   {view==="registration"&&<LiveAcademy focus="registration"/>}
   {view==="assignment"&&<LiveAcademy focus="assignment"/>}
   {view==="finance"&&<LiveFinance/>}
   {view==="programs"&&<Programs/>}
   {view==="reports"&&<LiveReports/>}
   {view==="users"&&<Users/>}
   {view==="new"&&<Registration done={()=>setView("customers")}/>} 
  </div></section>
  {panel&&<><div className="overlay" onClick={()=>setPanel(false)}/><aside className="drawer"><button className="close" onClick={()=>setPanel(false)}>×</button><div className="person"><i>{selected.name.slice(0,2)}</i><div><h2>{selected.name}</h2><p>{selected.id} · {selected.phone}</p></div></div><div className="actions"><button className="whatsapp" onClick={openWhatsApp}><FaWhatsapp size={17}/>واتساب</button><button onClick={()=>window.location.href=`tel:${selected.phone.replace(/\\s/g,"")}`}>اتصال</button></div><Section title="بيانات العميل والتسجيل"><div className="info customer-data"><label>البريد الإلكتروني<b>{selectedDetails.email||"—"}</b></label><label>رقم الجوال<b>{selected.phone}</b></label><label>البرنامج<b>{selected.program}</b></label><label>المسار<b>{selected.track}</b></label><label>قناة الشراء<b>{selected.source}</b></label><label>رقم الطلب<b>{selectedDetails.orderId||"—"}</b></label></div></Section><Section title="حالة العميل"><div className={`status ${selected.tone}`}><b>{selected.state}</b><span>{selected.due}</span></div><p className="workflow-help live-note">تتحدث هذه الحالة تلقائياً عند تنفيذ الإجراء من قائمة التواصل أو التسجيل أو الإسناد.</p></Section><Section title="الملخص المالي"><div className="money"><p>قيمة الطلب<b>{selected.total.toLocaleString()} ر.س</b></p><p>المحصل<b>{selected.paid.toLocaleString()} ر.س</b></p></div><div className="progress"><i style={{width:`${selected.paid/selected.total*100}%`}}/></div></Section><Section title="آخر النشاطات"><div className="timeline"><p>تم تحديث حالة التسجيل<small>الآن · {selected.owner}</small></p><p>تم إنشاء التسجيل في النظام<small>أمس، 16:20 · المبيعات</small></p></div></Section></aside></>}
 </main>
}

function Dashboard({open}:{open:(p:typeof people[number])=>void}){return <><div className="kpis"><Kpi title="طلبات هذا الشهر" value="128" tag="+12.5%" note="مقارنة بالشهر الماضي" tone="blue"/><Kpi title="بانتظار الأكاديمية" value="17" tag="5 عاجلة" note="تجاوزت وقت الاستلام" tone="amber"/><Kpi title="التحصيل هذا الشهر" value="184,250" tag="ر.س" note="من أصل 221,000 ر.س" tone="green"/><Kpi title="مستحقات متأخرة" value="23,500" tag="8 أقساط" note="تحتاج متابعة مالية" tone="red"/></div><div className="dashboard-grid"><Card title="الأولويات اليوم" action="عرض كل المهام"><TaskList/></Card><Card title="تدفق عمليات الأكاديمية" action="فتح لوحة الأكاديمية"><div className="flow">{[["17","جديد","gray"],["12","تم التواصل","violet"],["9","بانتظار التسجيل","amber"],["6","بانتظار الإسناد","blue"],["84","مكتمل","green"]].map(([n,l,t])=><div key={l}><i className={t}>{n}</i><span>{l}</span></div>)}</div><div className="sla"><span>متوسط إكمال التهيئة</span><b>1.8 يوم</b><em>الهدف: أقل من يومين</em></div></Card><div className="latest"><Card title="أحدث التسجيلات" action="عرض جميع التسجيلات"><CustomerTable list={people} open={open}/></Card></div><Card title="نبض التحصيل" action="التفاصيل المالية"><div className="ring"><div><b>83%</b><span>نسبة التحصيل</span></div></div><div className="legend"><p><i className="green"/>تم التحصيل<b>184,250 ر.س</b></p><p><i className="amber"/>قادم<b>13,250 ر.س</b></p><p><i className="red"/>متأخر<b>23,500 ر.س</b></p></div></Card></div></>}
function Work(){return <div className="board">{["متأخرة","اليوم","قادمة"].map((col,i)=><section key={col}><header><b>{col}</b><span>{[2,4,7][i]}</span></header>{tasks.slice(i===2?1:0,i===0?2:4).map(t=><article key={t[1]}><em className={t[4]}>{t[3]}</em><h3>{t[1]}</h3><p>{t[2]}</p><footer>◷ {t[0]}<i>{i===1?"ن":"ل"}</i></footer></article>)}</section>)}</div>}
function Customers({list,open}:{list:typeof people,open:(p:typeof people[number])=>void}){
 const[program,setProgram]=useState("الكل"),[source,setSource]=useState("الكل"),[status,setStatus]=useState("الكل");
 const programs=["الكل",...Array.from(new Set(people.map(p=>p.program)))];
 const sources=["الكل",...Array.from(new Set(people.map(p=>p.source)))];
 const filtered=list.filter(p=>(program==="الكل"||p.program===program)&&(source==="الكل"||p.source===source)&&(status==="الكل"||(status==="مكتمل"?p.state==="مكتمل":p.state!=="مكتمل")));
 const active=program!=="الكل"||source!=="الكل"||status!=="الكل";
 return <><div className="customer-summary"><div><span>إجمالي العملاء</span><b>{people.length}</b></div><div><span>النتائج المعروضة</span><b>{filtered.length}</b></div><div><span>برامج نشطة</span><b>{new Set(people.map(p=>p.program)).size}</b></div><div><span>يحتاجون إجراء</span><b>{people.filter(p=>p.state!=="مكتمل").length}</b></div></div><div className="card full customer-directory"><div className="directory-head"><div><h2>دليل العملاء</h2><p>ابحث من الشريط العلوي أو خصّص القائمة باستخدام التصفيات.</p></div>{active&&<button onClick={()=>{setProgram("الكل");setSource("الكل");setStatus("الكل")}}>× مسح التصفيات</button>}</div><div className="directory-filters"><label><span>البرنامج</span><select value={program} onChange={e=>setProgram(e.target.value)}>{programs.map(x=><option key={x}>{x}</option>)}</select></label><label><span>مصدر الشراء</span><select value={source} onChange={e=>setSource(e.target.value)}>{sources.map(x=><option key={x}>{x}</option>)}</select></label><label><span>حالة الملف</span><select value={status} onChange={e=>setStatus(e.target.value)}><option>الكل</option><option>نشط</option><option>مكتمل</option></select></label><div className="result-count"><b>{filtered.length}</b><span>عميل مطابق</span></div></div>{filtered.length?<CustomerTable list={filtered} open={open}/>:<div className="empty-results"><i>⌕</i><b>لا توجد نتائج مطابقة</b><p>جرّب تغيير البرنامج أو مصدر الشراء.</p></div>}</div></>
}
function Academy({open}:{open:(p:typeof people[number])=>void}){return <div className="kanban">{["جديد","تم التواصل","بانتظار التسجيل","بانتظار الإسناد","مكتمل"].map((col,i)=><section key={col}><header><b>{col}</b><span>{i===4?84:[3,2,2,1][i]}</span></header>{people.filter((_,n)=>i===4?n===3:n===i).map(p=><article key={p.id} onClick={()=>open(p)}><b>{p.name}</b><small>{p.id}</small><p>{p.program}</p><em>{p.due}</em><footer><span>{p.track}</span><i>{p.owner[0]}</i></footer></article>)}</section>)}</div>}
function Finance({open}:{open:(p:typeof people[number])=>void}){return <><div className="kpis"><Kpi title="إجمالي المستحق" value="221,000" tag="ر.س" note="الشهر الحالي" tone="blue"/><Kpi title="تم التحصيل" value="184,250" tag="83%" note="من إجمالي المستحق" tone="green"/><Kpi title="قادم خلال 7 أيام" value="13,250" tag="6 أقساط" note="تذكير تلقائي مجدول" tone="amber"/><Kpi title="متأخر" value="23,500" tag="8 أقساط" note="3 تحتاج تصعيد" tone="red"/></div><Card title="متابعة الأقساط" action="تصدير التقرير"><div className="table-wrap"><table><thead><tr><th>العميل</th><th>الطلب</th><th>المبلغ</th><th>الاستحقاق</th><th>الحالة</th><th/></tr></thead><tbody>{people.map((p,i)=><tr key={p.id}><td><b>{p.name}</b><small>{p.phone}</small></td><td>{p.id}</td><td><b>{["2,250","2,000","1,500","—"][i]} ر.س</b></td><td>{["اليوم","متأخر 3 أيام","27 يوليو","مسدد"][i]}</td><td><span className={`pill ${["amber","red","blue","green"][i]}`}>{["مستحق اليوم","متأخر","قادم","مسدد"][i]}</span></td><td><button className="link" onClick={()=>open(p)}>فتح الملف</button></td></tr>)}</tbody></table></div></Card></>}
function Reports(){return <div className="reports"><Card title="التسجيلات حسب البرنامج" action="آخر 30 يوم"><div className="bars">{[["تحليل السلوك التطبيقي",74],["إدارة السلوك التنظيمي",52],["التعليم المستمر",31],["الاقتصاد السلوكي",18]].map(([n,v])=><div key={n}><span>{n}</span><i><u style={{width:`${v}%`}}/></i><b>{v}</b></div>)}</div></Card><Card title="كفاءة رحلة التسجيل" action="هذا الشهر"><div className="metric"><b>1.8</b><span>يوم متوسط التهيئة</span><em>↓ 14% تحسن</em></div><div className="mini"><p><b>4.2 س</b>أول تواصل</p><p><b>91%</b>إكمال التسجيل</p><p><b>96%</b>دقة البيانات</p></div></Card></div>}

function Registration({done}:{done:()=>void}){
 const[step,setStep]=useState(1),[saved,setSaved]=useState(false),[saving,setSaving]=useState(false),[saveError,setSaveError]=useState("");
 const[programs,setPrograms]=useState<Program[]>([]);
 const[form,setForm]=useState({name:"",phone:"",email:"",journey:"شراء برنامج",programId:"PRG-ABA",program:"تحليل السلوك التطبيقي",track:"ABAT",delivery:"مسجل",language:"العربية",source:"عصارة",payment:"دفع كامل",method:"تحويل بنكي",amount:""});
 useEffect(()=>{apiJson("/api/programs").then(data=>{const list:Program[]=data.programs||[];setPrograms(list);const selected=list.find(p=>p.id===form.programId)||list[0];if(selected)setForm(f=>({...f,programId:selected.id,program:selected.name,track:selected.tracks?.[0]?.name||""}))}).catch(e=>setSaveError(e.message))},[]);
 const set=(key:string,value:string|boolean)=>setForm(f=>({...f,[key]:value}));
 const selectProgram=(programId:string)=>{const program=programs.find(p=>p.id===programId);if(program)setForm(f=>({...f,programId,program:program.name,track:program.tracks?.[0]?.name||""}))};
 const selectedProgram=programs.find(p=>p.id===form.programId);
 const asara=form.source==="عصارة";
 const submit=async()=>{setSaveError("");if(!form.name||!form.phone||!form.email){setSaveError("أكمل الاسم والجوال والبريد قبل الحفظ");setStep(1);return}setSaving(true);try{const payload={...form,mode:form.journey==="تجربة"?"trial":"payment",purchaseType:form.journey==="حجز مقعد"?"حجز مقعد":"برنامج"};const r=await fetch("/api/intake",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(data.error||"تعذر الحفظ");setSaved(true)}catch(e){setSaveError(e instanceof Error?e.message:"تعذر الحفظ في قاعدة البيانات")}finally{setSaving(false)}};
 const steps=["بيانات العميل","البرنامج والخدمة","الشراء والمالية","المراجعة"];
 if(saved)return <div className="register-success"><i>✓</i><h2>تم تسليم الطلب للعمليات</h2><p>{form.journey==="تجربة"?"بدأت التجربة وتم إنشاء مهمة متابعة للمبيعات.":form.journey==="حجز مقعد"?"تم إنشاء العميل وتأكيد حجز المقعد ومهمة المتابعة.":"تم إنشاء العميل والطلب والتسجيل ومهام الأكاديمية والمالية."}</p><div><button className="secondary" onClick={()=>setSaved(false)}>طلب جديد</button><button className="primary" onClick={done}>فتح قائمة العملاء</button></div></div>;
 return <div className="register-layout"><aside className="stepper">{steps.map((s,i)=><button key={s} className={step===i+1?"current":step>i+1?"complete":""} onClick={()=>setStep(i+1)}><i>{step>i+1?"✓":i+1}</i><span><b>{s}</b><small>{["الهوية ووسائل التواصل","اختيار المسار والتفاصيل","المصدر وخطة السداد","تدقيق وإنشاء الإجراءات"][i]}</small></span></button>)}</aside><section className="form-card">
  {step===1&&<><FormHead n="01" title="بيانات الطلب" text="اختاري سبب دخول الشخص للنظام؛ الدفع أو التجربة هما بوابة إنشاء العميل."/><div className="field-grid"><Field label="اسم العميل الكامل *"><input value={form.name} onChange={e=>set("name",e.target.value)} placeholder="مثال: سارة محمد العتيبي"/></Field><Field label="رقم الجوال *"><input value={form.phone} onChange={e=>set("phone",e.target.value)} placeholder="05xxxxxxxx"/></Field><Field label="البريد الإلكتروني *"><input value={form.email} onChange={e=>set("email",e.target.value)} placeholder="name@example.com"/></Field><Field label="نوع الرحلة"><select value={form.journey} onChange={e=>set("journey",e.target.value)}><option>شراء برنامج</option><option>حجز مقعد</option><option>تجربة</option></select></Field></div><div className="hint">لن يُنشأ العميل إلا عند تسجيل دفعة أو منحه تجربة من المبيعات.</div></>}
  {step===2&&<><FormHead n="02" title="البرنامج" text="تقييم الكفاءة برنامج مستقل، وحجز المقعد يحدد من نوع الرحلة في الخطوة السابقة."/><div className="field-grid"><Field label="البرنامج *"><select value={form.programId} onChange={e=>selectProgram(e.target.value)}>{programs.map(program=><option value={program.id} key={program.id}>{program.name}</option>)}</select></Field>{Boolean(selectedProgram?.tracks?.length)&&<Field label="المسار"><select value={form.track} onChange={e=>set("track",e.target.value)}>{selectedProgram?.tracks?.map(track=><option key={track.name}>{track.name}</option>)}</select></Field>}<Field label="نمط البرنامج"><select value={form.delivery} onChange={e=>set("delivery",e.target.value)}><option>مسجل</option><option>مباشر</option></select></Field><Field label="اللغة"><select value={form.language} onChange={e=>set("language",e.target.value)}><option>العربية</option><option>الإنجليزية</option></select></Field></div></>}
  {step===3&&<><FormHead n="03" title="الدفع" text={form.journey==="تجربة"?"التجربة لا تحتاج دفعة أو موافقة إدارية.":"تسجيل الإيصال ينشئ العميل فوراً؛ المالية تطابق العملية لاحقاً."}/><div className="source-grid">{["عصارة","سلة","دفع مباشر","تمارا","أخرى"].map(x=><button key={x} className={form.source===x?"selected":""} onClick={()=>set("source",x)}><i>{x==="عصارة"?"ع":x==="سلة"?"س":"◈"}</i><b>{x}</b><small>{x==="عصارة"?"تفعيل تلقائي":x==="تمارا"?"تقسيط خارجي":"مصدر الطلب"}</small></button>)}</div>{form.journey!=="تجربة"&&<div className="field-grid"><Field label="وسيلة الدفع"><select value={form.method} onChange={e=>set("method",e.target.value)}><option>تحويل بنكي</option><option>دفع إلكتروني</option><option>تمارا</option><option>نقدي</option></select></Field><Field label={form.journey==="حجز مقعد"?"رسوم حجز المقعد":"المبلغ المدفوع"}><input value={form.amount} onChange={e=>set("amount",e.target.value)} placeholder="0.00 ر.س"/></Field><Field label="خطة السداد"><select value={form.payment} onChange={e=>set("payment",e.target.value)}><option>دفع كامل</option><option>أقساط</option><option>تمارا</option></select></Field></div>}<div className={`automation-note ${form.journey==="تجربة"?"auto":"manual"}`}><i>✓</i><div><b>{form.journey==="تجربة"?"ستبدأ التجربة مباشرة":"لا يوجد انتظار لاعتماد المالية"}</b><p>{form.journey==="تجربة"?"سيحسب النظام مدة التجربة من إعداد البرنامج وينشئ متابعة للمبيعات.":"ستنشأ مهمة تنظيم ومطابقة للمالية دون تعطيل رحلة العميل."}</p></div></div></>}
  {step===4&&<><FormHead n="04" title="مراجعة الطلب" text="راجع نوع الرحلة والإجراءات التي سيُنشئها النظام قبل الحفظ."/><div className="review-grid"><section><h3>ملخص الطلب</h3><Review label="العميل" value={form.name||"لم يُدخل بعد"}/><Review label="نوع الرحلة" value={form.journey}/><Review label="البرنامج" value={`${form.program} · ${form.track}`}/><Review label="نمط الدراسة" value={`${form.delivery} · ${form.language}`}/><Review label="مصدر الشراء" value={form.source}/>{form.journey!=="تجربة"&&<><Review label="وسيلة الدفع" value={form.method}/><Review label="السداد" value={`${form.payment}${form.amount?` · ${form.amount} ر.س`:""}`}/></>}</section><section className="workflow-preview"><h3>الإجراءات التي ستُنشأ</h3><p className="done"><i>✓</i><span><b>{form.journey==="تجربة"?"إنشاء عميل تجربة":"إنشاء العميل والطلب فوراً"}</b><small>المبيعات · فوري</small></span></p>{form.journey==="تجربة"?<p className="next"><i>2</i><span><b>بدء التجربة وإنشاء المتابعة</b><small>المبيعات · حسب مدة البرنامج</small></span></p>:form.journey==="حجز مقعد"?<p className="next"><i>2</i><span><b>تأكيد الحجز ومتابعة موعد البدء</b><small>لا ينشئ تسجيلاً أكاديمياً الآن</small></span></p>:<><p className={asara?"done":"next"}><i>{asara?"✓":"2"}</i><span><b>{asara?"تفعيل الدورة تلقائياً عبر عصارة":"بدء رحلة التسجيل الأكاديمي"}</b><small>{asara?"لا يحتاج تدخلاً يدوياً":"الأكاديمية"}</small></span></p>{!asara&&<p className="next"><i>3</i><span><b>التواصل ثم إنشاء الحساب والإسناد</b><small>الأكاديمية</small></span></p>}</>} {form.journey!=="تجربة"&&<p className="finance-step"><i>ر.س</i><span><b>مطابقة وتنظيم الدفعة</b><small>المالية · لا تعطل رحلة العميل</small></span></p>}</section></div></>}
  {saveError&&<div className="save-error">{saveError}</div>}<footer className="wizard-actions"><button className="secondary" onClick={()=>step>1?setStep(step-1):done()}>{step>1?"السابق":"إلغاء"}</button><span>الخطوة {step} من 4</span>{step<4?<button className="primary" onClick={()=>setStep(step+1)}>التالي</button>:<button className="primary" disabled={saving} onClick={submit}>{saving?"جارٍ الحفظ...":"حفظ وتسليم للأقسام"}</button>}</footer>
 </section></div>
}
type LiveTask={id:string;title:string;department:string;priority:string;status:string;due_at?:string;assignee_email?:string};
type LiveEnrollment={id:string;status:string;customer_id:string;customer_name:string;phone:string;email:string;program_name:string;order_id:string;owner_email?:string};
type LiveReservation={id:string;status:string;customer_name:string;program_name:string;program_id:string;fee_amount:number;cohort_label?:string};
type LivePayment={payment_intent_id:string;reconciliation_status:string;amount:number;method:string;reference?:string;created_at:string;customer_id:string;customer_name:string;phone:string;email:string;program_name:string;order_id:string;order_type:string;purchase_source:string;payment_plan:string;order_total:number;order_paid:number};
type ProgramTrack={id?:string;name:string;active?:number};
type Program={id:string;name:string;code?:string;category?:string;trialDays?:number;seatFee?:number;active?:number;tracks?:ProgramTrack[]};

async function apiJson(url:string,init?:RequestInit){const response=await fetch(url,init);const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||"تعذر تحميل البيانات. تأكد من تسجيل الدخول والصلاحية.");return data}
function LiveState({loading,error,empty}:{loading:boolean;error:string;empty:boolean}){if(loading)return <div className="ops-empty">جارٍ تحميل البيانات الحية…</div>;if(error)return <div className="ops-error">{error}</div>;if(empty)return <div className="ops-empty">لا توجد بيانات بعد. ستظهر السجلات هنا فور إنشائها.</div>;return null}

type ReportRow={status?:string;department?:string;count:number;amount?:number;total_fees?:number};
type OperationsReport={generatedAt:string;prospects:ReportRow[];trials:ReportRow[];reservations:ReportRow[];enrollments:ReportRow[];tasks:ReportRow[];payments:ReportRow[];programs:{program_name:string;enrollment_count:number}[];customers:{count:number};orders:{count:number;total:number;paid:number}};
const totalCount=(rows:ReportRow[])=>(rows||[]).reduce((sum,row)=>sum+Number(row.count||0),0);
const stateCount=(rows:ReportRow[],state:string)=>Number((rows||[]).find(row=>row.status===state)?.count||0);
type TodayData={user:{email:string;name:string;roles:string[]};today:string;stats:{tasks:number;customers:number;payments:number;paymentAmount:number;enrollments:number};tasks:{id:string;title:string;department:string;priority:string;due_at?:string}[]};
function WelcomeToday({onOpenTasks}:{onOpenTasks:()=>void}){
 const[data,setData]=useState<TodayData|null>(null),[error,setError]=useState("");useEffect(()=>{apiJson("/api/dashboard/today").then(setData).catch(e=>setError(e.message))},[]);
 if(error)return <div className="ops-error compact">{error}</div>;if(!data)return <div className="welcome-panel loading">جارٍ تجهيز ملخص يومك…</div>;
 const roleLabel=data.user.roles.includes("admin")?"مدير النظام":data.user.roles.map(role=>roleNames[role]||role).join("، ");
 return <section className="welcome-panel"><div className="welcome-copy"><span>أهلاً، {data.user.name}</span><h2>اليوم لديك {data.stats.tasks} {data.stats.tasks===1?"مهمة":"مهام"} تحتاج متابعتك</h2><p>{roleLabel} · {data.user.email}</p><button onClick={onOpenTasks}>عرض مهامي اليوم ←</button></div><div className="today-stats"><article><i>✓</i><span>المهام المفتوحة</span><b>{data.stats.tasks}</b></article><article><i>＋</i><span>عملاء جدد اليوم</span><b>{data.stats.customers}</b></article><article><i>◎</i><span>تسجيلات قيد العمل</span><b>{data.stats.enrollments}</b></article><article><i>﷼</i><span>دفعات اليوم</span><b>{data.stats.payments}<small>{data.stats.paymentAmount.toLocaleString("ar-SA")} ر.س</small></b></article></div>{data.tasks.length>0&&<div className="today-task-strip"><b>الأولوية الآن</b>{data.tasks.slice(0,3).map(task=><span key={task.id}><i className={task.priority==="عاجلة"?"urgent":""}/>{task.title}<small>{task.department}</small></span>)}</div>}</section>
}
function LiveDashboard(){
 const[data,setData]=useState<OperationsReport|null>(null),[tasks,setTasks]=useState<LiveTask[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");
 useEffect(()=>{(async()=>{try{const[a,b]=await Promise.all([apiJson("/api/reports/operations"),apiJson("/api/tasks")]);setData(a);setTasks((b.tasks||[]).slice(0,5))}catch(e){setError((e as Error).message)}finally{setLoading(false)}})()},[]);
 if(loading||error||!data)return <LiveState loading={loading} error={error} empty={!data}/>;
 const due=totalCount(data.enrollments.filter(row=>row.status!=="مكتمل"));const paid=Number(data.orders?.paid||0),total=Number(data.orders?.total||0),ratio=total?Math.round(paid/total*100):0;
 return <><div className="kpis"><Kpi title="إجمالي العملاء" value={Number(data.customers?.count||0).toLocaleString("ar-SA")} tag="عميل" note="ملفات فعلية في النظام" tone="blue"/><Kpi title="رحلات عملاء نشطة" value={due.toLocaleString("ar-SA")} tag="تسجيل" note="تحتاج متابعة حتى الإكمال" tone="amber"/><Kpi title="قيمة المبيعات" value={total.toLocaleString("ar-SA")} tag="ر.س" note={`${Number(data.orders?.count||0)} طلب مسجل`} tone="green"/><Kpi title="حجوزات المقاعد" value={totalCount(data.reservations).toLocaleString("ar-SA")} tag="حجز" note="تشمل المؤكدة والمنقولة" tone="violet"/></div><div className="dashboard-grid"><Card title="أولويات العمل المفتوحة" action="بيانات حية"><div>{tasks.length?tasks.map(t=><div className="task" key={t.id}><i className={t.priority==="عاجلة"?"red":"amber"}/><div><b>{t.title}</b><span>{t.department} · {t.assignee_email||"غير مسندة"}</span></div><em className={t.priority==="عاجلة"?"red":"amber"}>{t.priority}</em></div>):<div className="ops-empty compact">لا توجد مهام مفتوحة.</div>}</div></Card><Card title="تقدّم رحلة العميل" action="حسب الحالة"><div className="flow">{data.enrollments.map((row,i)=><div key={row.status}><i className={["gray","violet","amber","blue","green"][i%5]}>{row.count}</i><span>{row.status}</span></div>)}</div></Card><Card title="رحلات النظام" action="ملخص مباشر"><div className="live-summary"><p><span>طلبات وتجارب</span><b>{totalCount(data.prospects)+totalCount(data.trials)}</b></p><p><span>طلبات شراء</span><b>{Number(data.orders?.count||0)}</b></p><p><span>تسجيلات العملاء</span><b>{totalCount(data.enrollments)}</b></p></div></Card><Card title="ملخص المبيعات" action="من الطلبات المسجلة"><div className="sales-summary"><p><span>عدد الطلبات</span><b>{Number(data.orders?.count||0)}</b></p><p><span>إجمالي قيمة المبيعات</span><b>{total.toLocaleString("ar-SA")} <small>ر.س</small></b></p><p><span>متوسط قيمة الطلب</span><b>{Number(data.orders?.count||0)?Math.round(total/Number(data.orders.count)).toLocaleString("ar-SA"):0} <small>ر.س</small></b></p></div></Card></div></>
}

function LiveReports(){
 const[data,setData]=useState<OperationsReport|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState("");useEffect(()=>{apiJson("/api/reports/operations").then(setData).catch(e=>setError(e.message)).finally(()=>setLoading(false))},[]);
 if(loading||error||!data)return <LiveState loading={loading} error={error} empty={!data}/>;const max=Math.max(...data.programs.map(x=>Number(x.enrollment_count)),1),openTasks=data.tasks.filter(x=>x.status!=="مكتملة");
 return <div className="reports"><Card title="التسجيلات حسب البرنامج" action="من قاعدة البيانات"><div className="bars">{data.programs.map(row=><div key={row.program_name}><span>{row.program_name}</span><i><u style={{width:`${Number(row.enrollment_count)/max*100}%`}}/></i><b>{row.enrollment_count}</b></div>)}</div></Card><Card title="كفاءة رحلة التسجيل" action="الوضع الحالي"><div className="metric"><b>{stateCount(data.enrollments,"مكتمل")}</b><span>رحلة مكتملة</span><em>{totalCount(data.enrollments)-stateCount(data.enrollments,"مكتمل")} رحلة قيد العمل</em></div><div className="mini"><p><b>{totalCount(data.trials)}</b>تجارب</p><p><b>{totalCount(data.reservations)}</b>حجوزات</p><p><b>{totalCount(openTasks)}</b>مهام مفتوحة</p></div></Card><Card title="عبء العمل حسب القسم" action="المهام غير المكتملة"><div className="bars">{Array.from(new Set(openTasks.map(x=>x.department||"غير محدد"))).map(dept=>{const count=openTasks.filter(x=>x.department===dept).reduce((s,x)=>s+Number(x.count),0);return <div key={dept}><span>{dept}</span><i><u style={{width:`${Math.min(count*12,100)}%`}}/></i><b>{count}</b></div>})}</div></Card><Card title="ملخص العمليات" action={new Date(data.generatedAt).toLocaleString("ar-SA")}><div className="live-summary"><p><span>العملاء</span><b>{data.customers.count}</b></p><p><span>الطلبات</span><b>{data.orders.count}</b></p><p><span>إجمالي المدفوع</span><b>{Number(data.orders.paid).toLocaleString("ar-SA")} ر.س</b></p></div></Card></div>
}

function LiveCustomers({query,open}:{query:string;open:(p:typeof initialPeople[number])=>void}){
 const[rows,setRows]=useState<typeof initialPeople>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");
 const load=()=>{apiJson("/api/customers").then(data=>setRows((data.customers||[]).map((row:Record<string,unknown>)=>{const state=String(row.state||row.order_status||"عميل");return{id:String(row.id),email:String(row.email||"محجوب حسب الصلاحية"),orderId:String(row.order_id||"—"),name:String(row.name||""),phone:String(row.phone||"محجوب حسب الصلاحية"),program:String(row.program_name||row.program||"لا يوجد طلب حالي"),track:String(row.track||"—"),source:String(row.source||row.admitted_via||"—"),owner:String(row.owner||"غير مسند"),state,tone:state==="مكتمل"||state==="مدفوع"?"green":state.includes("انتظار")?"amber":"blue",due:state==="مكتمل"?"لا إجراء مطلوب":"متابعة الملف",paid:Number(row.paid||0),total:Number(row.total||0)}}))).catch(e=>setError(e.message)).finally(()=>setLoading(false))};
 useEffect(()=>{void load();const refresh=()=>void load();window.addEventListener("sulukera:data-changed",refresh);return()=>window.removeEventListener("sulukera:data-changed",refresh)},[]);
 const filtered=rows.filter(row=>`${row.name} ${row.id} ${row.phone} ${row.program}`.includes(query));
 if(loading||error)return <LiveState loading={loading} error={error} empty={false}/>;
 return <><div className="customer-summary"><div><span>إجمالي العملاء</span><b>{rows.length}</b></div><div><span>النتائج المعروضة</span><b>{filtered.length}</b></div><div><span>برامج نشطة</span><b>{new Set(rows.map(row=>row.program).filter(x=>x!=="لا يوجد طلب حالي")).size}</b></div><div><span>يحتاجون إجراء</span><b>{rows.filter(row=>row.state!=="مكتمل").length}</b></div></div><div className="card full customer-directory"><div className="directory-head"><div><h2>دليل العملاء الحي</h2><p>النتائج مرتبطة مباشرة بقاعدة البيانات وتُعرض حسب صلاحية المستخدم.</p></div></div>{filtered.length?<CustomerTable list={filtered} open={open}/>:<LiveState loading={false} error="" empty/>}</div></>
}

function LiveWork(){
 const[rows,setRows]=useState<LiveTask[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");
 const load=async()=>{setLoading(true);setError("");try{setRows((await apiJson("/api/tasks")).tasks||[])}catch(e){setError((e as Error).message)}finally{setLoading(false)}};
 useEffect(()=>{void load()},[]);
 const act=async(taskId:string,action:string)=>{try{await apiJson("/api/tasks",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({taskId,action})});await load()}catch(e){setError((e as Error).message)}};
 const groups=["عاجلة","عالية","عادية"];
 if(loading||error||!rows.length)return <LiveState loading={loading} error={error} empty={!rows.length}/>;
 return <div className="board">{groups.map(priority=><section key={priority}><header><b>{priority}</b><span>{rows.filter(x=>x.priority===priority).length}</span></header>{rows.filter(x=>x.priority===priority).map(t=><article key={t.id}><em className={priority==="عاجلة"?"red":priority==="عالية"?"amber":"blue"}>{t.department}</em><h3>{t.title}</h3><p>{t.assignee_email||"غير مسندة"}</p><footer>{t.due_at?new Date(t.due_at).toLocaleDateString("ar-SA"):"دون موعد"}<button className="link" onClick={()=>act(t.id,"complete")}>إكمال</button><button className="link" onClick={()=>act(t.id,"assign")}>إسناد لي</button></footer></article>)}</section>)}</div>
}

const enrollmentSteps:Record<string,[string,string]>={"جديد":["contacted","تأكيد تسليم العميل"],"تم التواصل":["registered","إتمام تهيئة العميل"],"اكتمل التسجيل":["assigned","تفعيل المقررات"],"تم إنشاء الحساب":["assigned","تفعيل المقررات"],"تم الإسناد":["completed","إكمال البرنامج"],"نشط":["completed","إكمال البرنامج"]};
function LiveAcademy({focus}:{focus:"contact"|"registration"|"assignment"}){
 const[rows,setRows]=useState<LiveEnrollment[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(""),[moving,setMoving]=useState(""),[copied,setCopied]=useState("");
 const load=async()=>{setLoading(true);setError("");try{setRows((await apiJson("/api/enrollments")).enrollments||[])}catch(e){setError((e as Error).message)}finally{setLoading(false)}};useEffect(()=>{void load()},[]);
 const advance=async(row:LiveEnrollment)=>{const step=enrollmentSteps[row.status];if(!step)return;setMoving(row.id);try{await apiJson("/api/enrollments/transition",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({enrollmentId:row.id,action:step[0]})});setRows(current=>current.filter(item=>item.id!==row.id));window.dispatchEvent(new CustomEvent("sulukera:data-changed",{detail:{entity:"customer",id:row.customer_id}}));setTimeout(()=>void load(),350)}catch(e){setError((e as Error).message);setMoving("")}};
 const copy=async(value:string,key:string)=>{await navigator.clipboard.writeText(value);setCopied(key);setTimeout(()=>setCopied(""),1400)};
 const whatsapp=(row:LiveEnrollment)=>{const digits=row.phone.replace(/\D/g,"").replace(/^0/,"966");window.open(`https://wa.me/${digits}?text=${encodeURIComponent(`مرحباً ${row.customer_name}، معك فريق سلوكيرا بخصوص تهيئة تسجيلك في برنامج ${row.program_name}.`)}`,"_blank","noopener,noreferrer")};
 const displayState=(status:string)=>status==="تم إنشاء الحساب"?"اكتمل التسجيل":status==="نشط"?"تم الإسناد":status;
 const states=focus==="contact"?["جديد"]:focus==="registration"?["تم التواصل"]:["اكتمل التسجيل","تم الإسناد","مكتمل"];
 if(loading||error||!rows.length)return <LiveState loading={loading} error={error} empty={!rows.length}/>;
 const count=(state:string)=>rows.filter(x=>displayState(x.status)===state).length;
 const stageLabel=(state:string)=>focus==="contact"?"بانتظار تسليم العميل":focus==="registration"?"قيد تهيئة العميل":({"اكتمل التسجيل":"بانتظار التفعيل","تم الإسناد":"تم تفعيل المقررات","مكتمل":"مكتمل"} as Record<string,string>)[state]||state;
 const board=<div className={`kanban live-kanban simplified journey-board ${focus}`}>
  {states.map((state,index)=><section className={`journey-column column-${index}`} key={state}><header><div><i>{index+1}</i><b>{stageLabel(state)}</b></div><span>{count(state)}</span></header><p className="column-note">{focus==="assignment"?["جاهز لتفعيل البرنامج والمقررات","تم التفعيل ويجري تنفيذ البرنامج","أتم البرنامج بنجاح"][index]:focus==="contact"?"عملاء جاهزون للتسليم":"بيانات التواصل جاهزة للنسخ والإضافة"}</p><div className="column-cards">{rows.filter(x=>displayState(x.status)===state).map(row=><article className={moving===row.id?"card-moving":"card-enter"} key={row.id}><div className="journey-person"><i>{row.customer_name.slice(0,2)}</i><div><b>{row.customer_name}</b><small>{row.id}</small></div></div>{focus==="registration"&&<div className="onboarding-contact"><div><span><PhoneCall size={14}/>رقم الجوال</span><b dir="ltr">{row.phone}</b><button title="نسخ رقم الجوال" onClick={()=>copy(row.phone,`${row.id}-phone`)}><Copy size={14}/>{copied===`${row.id}-phone`?"تم النسخ":"نسخ"}</button></div><div><span><Mail size={14}/>البريد الإلكتروني</span><b dir="ltr">{row.email}</b><button title="نسخ البريد الإلكتروني" onClick={()=>copy(row.email,`${row.id}-email`)}><Copy size={14}/>{copied===`${row.id}-email`?"تم النسخ":"نسخ"}</button></div><div className="contact-quick-actions"><button className="whatsapp-mini" onClick={()=>whatsapp(row)}><FaWhatsapp size={15}/>واتساب</button><button onClick={()=>window.location.href=`tel:${row.phone.replace(/\s/g,"")}`}><PhoneCall size={14}/>اتصال</button><button onClick={()=>window.location.href=`mailto:${row.email}`}><Mail size={14}/>إرسال بريد</button></div></div>}<div className="journey-details"><p><span>البرنامج</span><b>{row.program_name}</b></p><p><span>رقم الطلب</span><b>{row.order_id}</b></p></div>{enrollmentSteps[row.status]&&<button className="academy-action" disabled={moving===row.id} onClick={()=>advance(row)}>{moving===row.id?"جارٍ النقل...":enrollmentSteps[row.status][1]} <span>←</span></button>}</article>)}</div>{!count(state)&&<div className="column-empty"><i>✓</i><b>لا توجد حالات هنا</b><span>ستظهر تلقائياً عند انتقال العميل</span></div>}</section>)}
 </div>;
 if(focus!=="assignment")return board;
 return <div className="assignment-workspace"><div className="assignment-banner"><div><span>مساحة تفعيل المقررات</span><h2>من التهيئة إلى تفعيل البرنامج</h2><p>راجعي العميل وفعّلي مقرراته، ثم تابعي اكتمال برنامجه من مكان واحد.</p></div><div className="assignment-stats"><p><span>بانتظار التفعيل</span><b>{count("اكتمل التسجيل")}</b></p><p><span>مقررات مفعّلة</span><b>{count("تم الإسناد")}</b></p><p><span>مكتمل</span><b>{count("مكتمل")}</b></p></div></div>{board}</div>
}

type StaffRow={email:string;role:string;active:number;created_at:string};
function Programs(){
 const[rows,setRows]=useState<Program[]>([]),[name,setName]=useState(""),[code,setCode]=useState(""),[category,setCategory]=useState("برنامج"),[trialDays,setTrialDays]=useState("0"),[seatFee,setSeatFee]=useState(""),[tracks,setTracks]=useState(""),[editingId,setEditingId]=useState(""),[editTracks,setEditTracks]=useState(""),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[error,setError]=useState("");
 const load=async()=>{setLoading(true);setError("");try{setRows((await apiJson("/api/programs?all=1")).programs||[])}catch(e){setError((e as Error).message)}finally{setLoading(false)}};useEffect(()=>{void load()},[]);
 const parseTracks=(value:string)=>value.split(/[,،\n]/).map(x=>x.trim()).filter(Boolean);
 const add=async()=>{setSaving(true);setError("");try{await apiJson("/api/programs",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name,code,category,trialDays,seatFee,tracks:parseTracks(tracks)})});setName("");setCode("");setTrialDays("0");setSeatFee("");setTracks("");await load()}catch(e){setError((e as Error).message)}finally{setSaving(false)}};
 const toggle=async(row:Program)=>{setSaving(true);setError("");try{await apiJson("/api/programs",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({programId:row.id,active:!row.active})});await load()}catch(e){setError((e as Error).message)}finally{setSaving(false)}};
 const saveTracks=async(row:Program)=>{setSaving(true);setError("");try{await apiJson("/api/programs",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({programId:row.id,tracks:parseTracks(editTracks)})});setEditingId("");await load()}catch(e){setError((e as Error).message)}finally{setSaving(false)}};
 return <div className="programs-layout">
  <section className="card program-form"><header><h2>إضافة برنامج جديد</h2><p>سيظهر البرنامج ومساراته تلقائياً في قائمة تسجيل العميل بعد حفظه.</p></header><div className="program-fields"><Field label="اسم البرنامج *"><input value={name} onChange={e=>setName(e.target.value)} placeholder="مثال: مهارات تعديل السلوك"/></Field><Field label="رمز البرنامج *"><input value={code} onChange={e=>setCode(e.target.value.toUpperCase())} placeholder="مثال: BMOD"/></Field><Field label="التصنيف"><select value={category} onChange={e=>setCategory(e.target.value)}><option>برنامج</option><option>شهادة</option><option>تقييم</option></select></Field><Field label="مدة التجربة بالأيام"><input type="number" min="0" value={trialDays} onChange={e=>setTrialDays(e.target.value)}/></Field><Field label="رسوم حجز المقعد"><input type="number" min="0" value={seatFee} onChange={e=>setSeatFee(e.target.value)} placeholder="اختياري"/></Field><Field label="المسارات"><input value={tracks} onChange={e=>setTracks(e.target.value)} placeholder="مثال: P، E، C"/></Field></div>{error&&<div className="ops-error compact">{error}</div>}<button className="primary" disabled={saving||!name||!code} onClick={add}>{saving?"جارٍ الحفظ...":"إضافة البرنامج"}</button></section>
  <Card title="البرامج الحالية" action={`${rows.filter(x=>x.active).length} مفعّل`}><LiveState loading={loading} error="" empty={!rows.length}/>{!loading&&rows.length>0&&<div className="program-list">{rows.map(row=><article className="program-row" key={row.id}><div className="program-mark"><BookOpenCheck size={19}/></div><div className="program-identity"><b>{row.name}</b><span>{row.code} · {row.category||"برنامج"}</span><em>{row.tracks?.length?row.tracks.map(x=>x.name).join(" · "):"دون مسارات"}</em>{editingId===row.id&&<div className="track-editor"><input value={editTracks} onChange={e=>setEditTracks(e.target.value)} placeholder="افصلي المسارات بفاصلة"/><button className="primary" onClick={()=>saveTracks(row)}>حفظ</button><button className="secondary" onClick={()=>setEditingId("")}>إلغاء</button></div>}</div><p><span>التجربة</span><b>{row.trialDays||0} يوم</b></p><p><span>حجز المقعد</span><b>{row.seatFee?`${Number(row.seatFee).toLocaleString("ar-SA")} ر.س`:"غير محدد"}</b></p><i className={`pill ${row.active?"green":"red"}`}>{row.active?"مفعّل":"موقوف"}</i><div className="program-actions"><button className="link" onClick={()=>{setEditingId(row.id);setEditTracks(row.tracks?.map(x=>x.name).join("، ")||"")}}>تعديل المسارات</button><button className={`permission-toggle ${row.active?"stop":"start"}`} disabled={saving} onClick={()=>toggle(row)}>{row.active?"إيقاف":"تفعيل"}</button></div></article>)}</div>}</Card>
 </div>
}
const roleNames:Record<string,string>={admin:"الإدارة",sales:"المبيعات",finance:"المالية",academy:"تفعيل المقررات",viewer:"مشاهدة فقط"};
function Users(){
 const[staff,setStaff]=useState<StaffRow[]>([]),[email,setEmail]=useState(""),[role,setRole]=useState("sales"),[loading,setLoading]=useState(true),[error,setError]=useState(""),[saving,setSaving]=useState(false),[updating,setUpdating]=useState(""),[showGuide,setShowGuide]=useState(false);
 const load=async()=>{setLoading(true);setError("");try{setStaff((await apiJson("/api/staff")).staff||[])}catch(e){setError((e as Error).message)}finally{setLoading(false)}};useEffect(()=>{void load()},[]);
 const save=async(targetEmail:string,targetRole:string,active=true)=>{const key=`${targetEmail}-${targetRole}`;setSaving(true);setUpdating(key);setError("");setStaff(current=>current.map(row=>row.email===targetEmail&&row.role===targetRole?{...row,active:active?1:0}:row));try{await apiJson("/api/staff",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({email:targetEmail,role:targetRole,active})});setEmail("");await load()}catch(e){setError((e as Error).message);await load()}finally{setSaving(false);setUpdating("")}};
 return <div className="users-layout"><section className="card user-form"><header><h2>إضافة مستخدم</h2><p>أضيفي بريد الموظف ثم حددي القسم الذي يستطيع التعامل معه.</p></header><label><span>البريد الإلكتروني</span><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com"/></label><label><span>الصلاحية</span><select value={role} onChange={e=>setRole(e.target.value)}>{Object.entries(roleNames).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>{error&&<div className="ops-error compact">{error}</div>}<button className="primary" disabled={saving||!email} onClick={()=>save(email,role)}>{saving?"جارٍ الحفظ...":"إضافة المستخدم"}</button></section><Card title="المستخدمون الحاليون" action={showGuide?"إخفاء شرح الصلاحيات":"شرح صلاحيات النظام"} onAction={()=>setShowGuide(!showGuide)}>{showGuide&&<div className="permissions-guide"><b>ماذا تسمح كل صلاحية؟</b><p><strong>الإدارة:</strong> جميع الشاشات وإدارة المستخدمين. <strong>المبيعات:</strong> العملاء والتواصل والتسجيل. <strong>المالية:</strong> الدفعات والمطابقة. <strong>الإسناد:</strong> إسناد البرامج. <strong>المشاهدة:</strong> قراءة فقط دون تعديل.</p></div>}{error&&<div className="ops-error compact">{error}</div>}<LiveState loading={loading} error="" empty={!staff.length}/>{!loading&&staff.length>0&&<div className="table-wrap"><table><thead><tr><th>البريد</th><th>الصلاحية</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{staff.map(row=><tr className={updating===`${row.email}-${row.role}`?"updating":""} key={`${row.email}-${row.role}`}><td><b>{row.email}</b></td><td>{roleNames[row.role]||row.role}</td><td><span className={`pill ${row.active?"green":"red"}`}>{row.active?"مفعّل":"موقوف"}</span></td><td><button className={`permission-toggle ${row.active?"stop":"start"}`} disabled={saving} onClick={()=>save(row.email,row.role,!row.active)}>{updating===`${row.email}-${row.role}`?(row.active?"جارٍ التفعيل...":"جارٍ الإيقاف..."):(row.active?"إيقاف الصلاحية":"إعادة التفعيل")}</button></td></tr>)}</tbody></table></div>}</Card></div>
}

function Reservations(){
 const[rows,setRows]=useState<LiveReservation[]>([]),[programs,setPrograms]=useState<Program[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");
 const load=async()=>{setLoading(true);setError("");try{const[a,b]=await Promise.all([apiJson("/api/reservations"),apiJson("/api/programs")]);setRows(a.reservations||[]);setPrograms(b.programs||[])}catch(e){setError((e as Error).message)}finally{setLoading(false)}};useEffect(()=>{void load()},[]);
 const post=async(body:Record<string,string>)=>{try{await apiJson("/api/reservations",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});await load()}catch(e){setError((e as Error).message)}};
 const transfer=(row:LiveReservation)=>{const target=programs.find(p=>p.id!==row.program_id);if(!target){setError("لا يوجد برنامج آخر متاح للنقل.");return}void post({action:"request_transfer",reservationId:row.id,targetProgramId:target.id,targetCohortLabel:"الدفعة القادمة"})};
 if(loading||error||!rows.length)return <LiveState loading={loading} error={error} empty={!rows.length}/>;
 return <Card title="الحجوزات الفعلية" action="تتحدث تلقائياً"><div className="table-wrap"><table><thead><tr><th>العميل</th><th>البرنامج</th><th>رسوم الحجز</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td><b>{row.customer_name}</b><small>{row.id}</small></td><td>{row.program_name}<small>{row.cohort_label||"دون دفعة محددة"}</small></td><td>{Number(row.fee_amount).toLocaleString("ar-SA")} ر.س</td><td><span className="pill blue">{row.status}</span></td><td><div className="ops-actions">{row.status==="مؤكد"&&<><button className="link" onClick={()=>post({action:"convert_to_enrollment",reservationId:row.id})}>بدء البرنامج</button><button className="link" onClick={()=>transfer(row)}>طلب نقل</button></>}</div></td></tr>)}</tbody></table></div></Card>
}

function LiveFinance(){
 const[rows,setRows]=useState<LivePayment[]>([]),[summary,setSummary]=useState({total:0,count:0,reconciled:0,flagged:0}),[loading,setLoading]=useState(true),[error,setError]=useState(""),[selectedPayment,setSelectedPayment]=useState<LivePayment|null>(null);
 const load=async()=>{setLoading(true);setError("");try{const data=await apiJson("/api/finance");setRows(data.payments||[]);setSummary(data.summary||summary)}catch(e){setError((e as Error).message)}finally{setLoading(false)}};useEffect(()=>{void load()},[]);
 const review=async(paymentIntentId:string,action:"reconcile"|"flag")=>{const note=action==="flag"?"تحتاج مراجعة بيانات الإيصال":"";try{await apiJson("/api/payments/review",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({paymentIntentId,action,note})});setSelectedPayment(null);await load()}catch(e){setError((e as Error).message)}};
 return <>{<div className="kpis"><Kpi title="إجمالي الدفعات" value={Number(summary.total).toLocaleString("ar-SA")} tag="ر.س" note={`${summary.count} عملية`} tone="blue"/><Kpi title="تمت المطابقة" value={Number(summary.reconciled).toLocaleString("ar-SA")} tag="ر.س" note="إجراء تنظيمي فقط" tone="green"/><Kpi title="تحتاج مراجعة" value={Number(summary.flagged).toLocaleString("ar-SA")} tag="ر.س" note="لا توقف رحلة العميل" tone="amber"/></div>}<LiveState loading={loading} error={error} empty={!rows.length}/>{!loading&&!error&&rows.length>0&&<Card title="مطابقة الإيصالات" action="لا تحتاج اعتماداً"><div className="table-wrap"><table><thead><tr><th>العميل</th><th>البرنامج</th><th>المبلغ</th><th>الوسيلة</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{rows.map(row=><tr onClick={()=>setSelectedPayment(row)} key={row.payment_intent_id}><td><b>{row.customer_name}</b><small>{row.order_id}</small></td><td>{row.program_name}</td><td><b>{Number(row.amount).toLocaleString("ar-SA")} ر.س</b></td><td>{row.method}<small>{row.reference||"دون مرجع"}</small></td><td><span className="pill blue">{row.reconciliation_status}</span></td><td><div className="ops-actions"><button className="link" onClick={e=>{e.stopPropagation();void review(row.payment_intent_id,"reconcile")}}>تمت المطابقة</button><button className="link" onClick={e=>{e.stopPropagation();void review(row.payment_intent_id,"flag")}}>وضع للمراجعة</button></div></td></tr>)}</tbody></table></div></Card>}{selectedPayment&&<><div className="overlay" onClick={()=>setSelectedPayment(null)}/><aside className="drawer finance-drawer"><button className="close" onClick={()=>setSelectedPayment(null)}>×</button><div className="person"><i>﷼</i><div><h2>{selectedPayment.customer_name}</h2><p>{selectedPayment.customer_id} · {selectedPayment.phone}</p></div></div><Section title="بيانات العميل"><div className="info customer-data"><label>البريد الإلكتروني<b>{selectedPayment.email}</b></label><label>رقم الجوال<b>{selectedPayment.phone}</b></label><label>البرنامج<b>{selectedPayment.program_name}</b></label><label>مصدر الشراء<b>{selectedPayment.purchase_source||"—"}</b></label></div></Section><Section title="تفاصيل الطلب"><div className="info customer-data"><label>رقم الطلب<b>{selectedPayment.order_id}</b></label><label>نوع الطلب<b>{selectedPayment.order_type}</b></label><label>خطة السداد<b>{selectedPayment.payment_plan}</b></label><label>إجمالي الطلب<b>{Number(selectedPayment.order_total).toLocaleString("ar-SA")} ر.س</b></label><label>المدفوع<b>{Number(selectedPayment.order_paid).toLocaleString("ar-SA")} ر.س</b></label><label>المتبقي<b>{Math.max(Number(selectedPayment.order_total)-Number(selectedPayment.order_paid),0).toLocaleString("ar-SA")} ر.س</b></label></div></Section><Section title="الدفعة الحالية"><div className="payment-card"><div><span>المبلغ</span><b>{Number(selectedPayment.amount).toLocaleString("ar-SA")} ر.س</b></div><p><span>الوسيلة</span><b>{selectedPayment.method}</b></p><p><span>المرجع</span><b>{selectedPayment.reference||"دون مرجع"}</b></p><p><span>الحالة</span><b>{selectedPayment.reconciliation_status}</b></p><p><span>تاريخ التسجيل</span><b>{new Date(selectedPayment.created_at).toLocaleString("ar-SA")}</b></p></div><div className="finance-actions"><button className="primary" onClick={()=>review(selectedPayment.payment_intent_id,"reconcile")}>تمت المطابقة</button><button className="secondary" onClick={()=>review(selectedPayment.payment_intent_id,"flag")}>تحتاج مراجعة</button></div></Section></aside></>}</>
}

function FormHead({n,title,text}:{n:string,title:string,text:string}){return <header className="form-head"><i>{n}</i><div><h2>{title}</h2><p>{text}</p></div></header>}
function Field({label,children}:{label:string,children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function Review({label,value}:{label:string,value:string}){return <p className="review-row"><span>{label}</span><b>{value}</b></p>}

function Kpi({title,value,tag,note,tone}:{title:string,value:string,tag:string,note:string,tone:string}){return <article className={`kpi ${tone}`}><span>{title}</span><div><b>{value}</b><em>{tag}</em></div><p>{note}</p></article>}
function Card({title,action,children,onAction}:{title:string,action:string,children:React.ReactNode,onAction?:()=>void}){return <section className="card"><header className="card-head"><h2>{title}</h2>{onAction?<button onClick={onAction}>{action} ←</button>:<span>{action}</span>}</header>{children}</section>}
function Section({title,children}:{title:string,children:React.ReactNode}){return <section className="drawer-section"><h3>{title}</h3>{children}</section>}
function TaskList(){return <div>{tasks.map(t=><div className="task" key={t[1]}><time>{t[0]}</time><i className={t[4]}/><div><b>{t[1]}</b><span>{t[2]}</span></div><em className={t[4]}>{t[3]}</em><button>⋯</button></div>)}</div>}
function CustomerTable({list,open}:{list:typeof people,open:(p:typeof people[number])=>void}){return <div className="table-wrap"><table><thead><tr><th>العميل</th><th>البرنامج</th><th>قناة الشراء</th><th>حالة العميل</th><th>الخطوة التالية</th></tr></thead><tbody>{list.map(p=><tr key={p.id} onClick={()=>open(p)}><td><b>{p.name}</b><small>{p.id} · {p.phone}</small></td><td><b>{p.program}</b><small>{p.track}</small></td><td>{p.source}</td><td><span className={`pill ${p.tone}`}>{p.state}</span></td><td>{p.due}</td></tr>)}</tbody></table></div>}
